document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("stats-grid");n&&(n.innerHTML=SIDHU_INFO.quickStats.map(n=>`\n                <div class="stat-pill">\n                    <span class="stat-icon">${n.icon}</span>\n                    <span class="stat-value">${n.value}</span>\n                    <span class="stat-label">${n.label}</span>\n                </div>\n            `).join(""));const e=document.getElementById("history-content");e&&(e.innerHTML=`\n            <h3>${HISTORY_TEXT.title}</h3>\n            ${HISTORY_TEXT.paragraphs.map(n=>`<p>${n}</p>`).join("")}\n        `);const t=document.getElementById("sm-timeline");t&&(t.innerHTML=TIMELINE_EVENTS.map(n=>`\n                <div class="timeline-item">\n                    <div class="timeline-dot"></div>\n                    <div class="timeline-content">\n                        <span class="timeline-era">${n.era}</span>\n                        <h4>${n.title}</h4>\n                        <p>${n.description}</p>\n                    </div>\n                </div>\n            `).join(""));const i=document.getElementById("rebellion-grid");i&&(i.innerHTML=REBELLION_POINTS.map(n=>`\n                <div class="sm-card">\n                    <h4>${n.title}</h4>\n                    <p>${n.description}</p>\n                </div>\n            `).join(""));const s=document.getElementById("significance-content");s&&(s.innerHTML=SIGNIFICANCE_TEXT.paragraphs.map(n=>`<p>${n}</p>`).join(""));const a=document.getElementById("sm-gallery");a&&(a.innerHTML=GALLERY_QUERIES.map(n=>`<div class="sm-gallery-tile"><span>${n}</span></div>`).join(""));const l=document.getElementById("references-list");l&&(l.innerHTML=REFERENCES.map(n=>`<li><a href="${n.link}" target="_blank" rel="noopener">${n.text}</a></li>`).join(""))});